# --- Independent reimplementation from the prose spec in scoring.py's docstrings ---
def my_normalize(s):
    # "whitespace fold + lower"
    return " ".join((s or "").lower().split())

def my_tokens(s, pattern=r"\w+"):
    return re.findall(pattern, my_normalize(s), re.UNICODE)

def my_boundary(answer, gold, pattern=r"\w+"):
    g = my_tokens(gold, pattern)
    if not g: return False
    a = my_tokens(answer, pattern)
    m = len(g)
    return any(a[i:i+m]==g for i in range(len(a)-m+1))

def my_c34(answer, gold):
    g = my_normalize(gold)
    return bool(g) and g in my_normalize(answer)

