from math import comb
def mcnemar_exact(a_only,b_only):
    n=a_only+b_only
    if n==0: return 1.0
    k=min(a_only,b_only)
    p=sum(comb(n,i) for i in range(0,k+1))/2**n*2
    return min(1.0,p)
